"""Complete source-compared French dressings and vinaigrettes."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def mix(extra=()):return ['In a small bowl, whisk {{vinegar}}, {{salt}} and {{pepper}}'+(' with '+', '.join(tk(k) for k in extra) if extra else '')+' until the salt is dissolved.','Gradually whisk in {{oil}} until evenly blended. Toss with the salad immediately before serving.',STORE]

r=add(153,'Finnish-American Pickle and Green Pepper Vinaigrette',7,10,'Chopped pickles, green pepper and parsley give this oil-and-vinegar dressing a fresh, tangy crunch.',[oil(75),vinegar(30),I('pickle',1,'tbsp','drained cucumber pickles, finely chopped','Use the same amount of drained chopped cornichons.'),I('greenpepper',.5,'tbsp','green bell pepper, finely chopped','Use the same amount of red bell pepper.'),parsley(),salt(.25),pepper(.125)],mix()[:2]+['Stir in {{pickle}}, {{greenpepper}} and {{parsley}}. Spoon the chopped vegetables evenly over each portion.']+[STORE],'The 1914 and 1928 original scans show the same 5:2 oil-to-vinegar formula, identical pickle, parsley and half-tablespoon green-pepper quantities and the same mixing method. The extracted 1928 quarter-tablespoon was a transcription error. Salt and pepper amounts are supplied. About seven small dressing portions. Both source credits and the alternate saved ID are retained.')
s=src(154);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason='Identical formula and method after original-page correction: both use half a tablespoon of green pepper.');r['source']+=' Equivalent source retained: '+s['recipe']['source'];r['sourceAliases'].append(s['id']);records.pop(s['id'],None)

r=add(146,'Garlic-Rubbed Vinaigrette with Gherkin and Tarragon',8,10,'Tarragon vinegar, grated onion, chopped gherkin and a little hot sauce flavor this garlic-scented dressing.',[I('garlic',1,'clove','peeled garlic','Omit for a garlic-free dressing.'),salt(),I('pepper',.125,'tsp','ground white pepper','Use the same amount of black pepper.'),I('water',5,'ml','cold drinking water','Use the same volume of cold drinking water; this replaces the source ice option.'),oil(60),I('hotsauce',.5,'ml','Tabasco-style hot pepper sauce','Use the same volume of another vinegar-based hot sauce, or omit.'),vinegar(30,'tarragon'),I('onion',1,'tbsp','finely grated onion','Use the same amount of grated shallot.'),parsley(3),I('gherkin',20,'g','drained pickled gherkin, finely chopped','Use the same weight of drained cucumber pickle.')],['Cut {{garlic}} in half and rub the cut sides around a clean mixing bowl. Discard the clove.','Whisk {{water}}, {{vinegar}}, {{salt}}, {{pepper}} and {{hotsauce}} in the bowl until the salt dissolves. Gradually whisk in {{oil}}.','Stir in {{onion}}, {{parsley}} and {{gherkin}}. Serve a little over each salad portion.',STORE],'The salt is dissolved in the water and vinegar before adding oil. Ten drops of sauce become an explicit modern 0.5 ml approximation; drop sizes vary. One gherkin becomes 20 g. Cold water is chosen instead of ice so no undissolved ice needs removing.')

r=add(156,'Boston Herb and Pickle Vinaigrette',10,10,'Cider and tarragon vinegars combine with olive oil, paprika, pickles, green pepper and fresh herbs.',[salt(1),I('paprika',.25,'tsp','sweet paprika','Use the same amount of smoked paprika for a different flavor.'),pepper(.0625),vinegar(15,'tarragon'),I('cider',30,'ml','cider vinegar','Use the same volume of white wine vinegar.'),oil(90),I('pickle',1,'tbsp','drained cucumber pickle, finely chopped','Use the same amount of chopped cornichons.'),I('greenpepper',1,'tbsp','green bell pepper, finely chopped','Use the same amount of red bell pepper.'),parsley(),I('chives',1,'tsp','fresh chives, finely chopped','Use the same amount of finely sliced green onion tops.')],mix(['paprika','cider'])[:2]+['Stir in {{pickle}}, {{greenpepper}}, {{parsley}} and {{chives}}. Distribute the chopped ingredients evenly when serving.']+[STORE],'The original three tablespoons total vinegar and six tablespoons oil are retained. A few grains of pepper become 1/16 teaspoon. This differs from the Finnish-American dressing in its ratio, cider and tarragon vinegars, paprika and chives.')

r=add(195,'Manila French Dressing',5,5,'A simple, oil-rich dressing balances olive oil and vinegar with salt and black pepper.',[salt(.75),pepper(.25),oil(60),vinegar(15)],mix(),'The source 4:1 oil-to-acid ratio is retained. One saltspoon of pepper is interpreted as a modern quarter teaspoon. The original lemon option is kept as a complete variation. Salt is dissolved in the acid before oil is added.')
variant(r,'lemon','Manila lemon dressing',[dict(i,name='lemon juice',substitution='Use the vinegar base recipe if preferred.') if i['key']=='vinegar' else copy.deepcopy(i) for i in r['ingredients']],[t.replace('oil and vinegar naturally separate','oil and lemon juice naturally separate') for t in r['steps']])

r=add(196,'Sweet Paprika French Dressing',6,5,'A little sugar and paprika soften this brisk olive-oil and vinegar dressing.',[salt(),pepper(),I('sugar',1,'tsp','granulated sugar','Use the same amount of caster sugar.'),I('paprika',.125,'tsp','sweet paprika','Use the same amount of smoked paprika for a different flavor.'),vinegar(30),oil(60)],mix(['sugar','paprika']),'The source half-teaspoon salt, quarter-teaspoon pepper, teaspoon sugar and 2:1 oil-to-vinegar ratio are retained. The dash of paprika is supplied as 1/8 teaspoon. This sweet paprika version remains distinct from the plain Boston dressing.')

r=add(198,'Creole Mustard and Cooked-Yolk French Dressing',5,30,'Mashed cooked egg yolk and mustard thicken a small, tangy olive-oil dressing.',[oil(45),vinegar(15),I('mustard',1,'tsp','prepared Dijon mustard','Use the same amount of prepared yellow mustard for a milder flavor.'),I('egg',1,'','large egg','Use one large pasteurized shell egg if preferred; cook it fully as directed.'),I('water',750,'ml','water for boiling the egg','Use enough drinking water to cover the egg by about 2 cm in a small pan.'),salt(.25),pepper(.125)],['Put {{egg}} in a small pan with {{water}}. Add more water if necessary to cover by about 2 cm. Bring to a boil, cover, remove from the heat and stand for 12 minutes. Cool immediately under cold running water until safe to handle. Peel and cut open; the yolk must be firm throughout. Keep the cooked white refrigerated for another dish.','Mash the cooked yolk very finely in a bowl. Whisk in {{mustard}}, {{vinegar}}, {{salt}} and {{pepper}} until smooth.','Add {{oil}} slowly while whisking until creamy and blended. Serve with the salad.',STORE],'Prepared mustard, seasoning amounts and a complete egg-cooking method are supplied. Only the yolk goes into the dressing; the cooked white is not an extra unlisted ingredient. This is an egg-containing fresh dressing.')

r=add(199,'Tarragon and Onion French Dressing',5,10,'Tarragon vinegar, onion juice, finely chopped onion and parsley give this dressing a sharp, savory flavor.',[oil(45),vinegar(15,'tarragon'),salt(.25),pepper(.25),I('onion',60,'g','peeled onion','Use the same weight of shallot for a different flavor.'),parsley(3)],['Finely chop {{onion|0.16666666666666666}}. Grate {{onion|0.8333333333333334}} into a fine sieve over a bowl and press firmly with a spoon to extract its juice; discard the pressed pulp.','Whisk the extracted onion juice with {{vinegar}}, {{salt}} and {{pepper}}. Gradually whisk in {{oil}} until blended.','Stir in the reserved chopped onion and {{parsley}}. Spoon over the salad just before serving.',STORE],'The source lists chopped onion as well as juice of half an onion. The modern 60 g total is divided into 10 g chopped and 50 g grated for juice; the amount of juice recovered varies. The saltspoons are interpreted as quarter teaspoons. Parsley is supplied as one tablespoon.')

r=add(200,'Peppery Creole French Dressing',4,5,'A pepper-forward olive-oil and vinegar dressing for simple green salads.',[oil(45),vinegar(15),salt(),pepper(.5)],mix(),'The source half-teaspoon black pepper is retained. This is twice the pepper in the comparable 1914 Finnish-American dressing and is kept as a distinct pepper-forward formula.')
r=add(201,'Finnish-American French Dressing',4,5,'Olive oil, vinegar, salt and black pepper make a simple dressing with a three-to-one oil-to-vinegar ratio.',[oil(45),vinegar(15),salt(),pepper()],mix(),'The original 1914 printed page196 clearly gives quarter-teaspoon pepper, correcting the extracted three-quarter teaspoon. The source plain salad oil is interpreted as olive oil; a mild neutral oil is the substitution.')
r=add(202,'Ranskalainen Salaattikastike with Lemon and Vinegar',5,5,'This Finnish French dressing combines vinegar and lemon juice with olive oil and black pepper.',[oil(45),vinegar(15),I('lemon',7.5,'ml','lemon juice','Use the same volume of lime juice for a different flavor.'),pepper(),salt()],mix(['lemon']),'The full 1928 printed page237 includes lemon juice missing from the extracted instructions, a lemon-only option using two tablespoons juice, and onion-juice or grated Roquefort options. The latter flavoring quantities are supplied modern choices. These additions distinguish it from the earlier plain dressing.')
li=[dict(i,amount=30,name='lemon juice',substitution='Use the lemon-and-vinegar base if preferred.') if i['key']=='vinegar' else copy.deepcopy(i) for i in r['ingredients'] if i['key']!='lemon'];variant(r,'lemon-only','Lemon-only Finnish dressing',li,mix())
for key,label,item,prep in [('onion','With onion juice',I('onion',30,'g','peeled onion','Use the same weight of shallot.'),'Grate {{onion}} into a fine sieve set over the mixing bowl. Press firmly with a spoon and discard the pulp; keep all the extracted juice in the bowl.'),('roquefort','With Roquefort',I('roquefort',10,'g','Roquefort cheese','Use the same weight of another crumbly blue cheese.'),'Finely crumble {{roquefort}} into the finished dressing and whisk to distribute it.')]:
 st=copy.deepcopy(r['steps']);st.insert(0 if key=='onion' else 2,prep);variant(r,key,label,copy.deepcopy(r['ingredients'])+[item],st)

r=add(203,'Club French Dressing with Brandy',6,5,'Uncooked brandy and tarragon vinegar make a sharp, aromatic dressing with olive oil.',[salt(),pepper(),I('brandy',30,'ml','brandy','Use the same volume of unsweetened white grape juice for an alcohol-free ingredient substitution with a sweeter flavor.'),vinegar(30,'tarragon'),oil(30)],mix(['brandy']),'The equal quantities of brandy, vinegar and oil are retained. The brandy is not cooked and its alcohol remains in the dressing; this base recipe is not alcohol-free.')
r=add(204,'Boston Plain French Dressing',6,5,'A brisk two-to-one olive-oil and vinegar dressing seasoned simply with salt and pepper.',[salt(),pepper(),vinegar(30),oil(60)],mix(),'The original 2:1 oil-to-vinegar ratio and seasoning amounts are retained. No sugar or paprika is added, unlike the Greenbaum dressing.')
r=add(205,'Parisian French Dressing with Pickled Hot Peppers',14,75,'Small pickled red and green hot peppers infuse an olive-oil dressing with onion, parsley and a little sugar.',[oil(120),vinegar(75),I('sugar',.5,'tsp','powdered sugar','Use the same amount of caster sugar and whisk until dissolved.'),I('onion',1,'tbsp','sweet onion, finely chopped','Use the same amount of finely chopped shallot.'),parsley(6),I('redpeppers',8,'g','drained small pickled red hot peppers, about four tiny peppers','Use the same weight of pickled green hot peppers; heat varies by variety.'),I('greenpeppers',16,'g','drained small pickled green hot peppers, about eight tiny peppers','Use the same weight of pickled red hot peppers; heat varies by variety.'),salt(1)],['Trim any stems from {{redpeppers}} and {{greenpeppers}} and chop finely. Wash hands after handling hot peppers; avoid touching your eyes.','Whisk {{vinegar}}, {{sugar}} and {{salt}} until dissolved. Gradually whisk in {{oil}}, then stir in {{onion}}, {{parsley}} and the chopped peppers.','Cover and refrigerate for 1 hour. Whisk vigorously for about 5 minutes before spooning over salad, distributing the pepper pieces evenly.',STORE],'The original specifies tiny peppers from pepper sauce, not twelve bell peppers. Modern weights of 8 g red and 16 g green are supplied to make that scale explicit; actual heat varies. Half a cup oil becomes 120 ml. The one-hour infusion takes place in the refrigerator. About fourteen small dressing portions.')

assert len(newids)==13,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full dressing formula and method compared; measurements, descriptions, substitutions and variants completed','repair-batch-018.py'))
s=src(154);db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-merge',aliases[s['id']]['reason'],'repair-batch-018.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=1,totalOverrides=len(records),totalAliases=len(aliases))))
